pub fn norm(mut xs: Vec<i32>) -> Vec<i32> {
    xs.dedup();
    xs.sort();
    xs
}
#[cfg(test)] mod tests { use super::*; #[test] fn contract() { assert_eq!(norm(vec![]), Vec::<i32>::new()); assert_eq!(norm(vec![7]), vec![7]); assert_eq!(norm(vec![7,8,7,-2,8]), vec![-2,7,8]); assert_eq!(norm(vec![7,7,8]), vec![7,8]); } }

pub fn norm(mut xs: Vec<String>) -> Vec<String> {
    xs.dedup();
    xs.sort();
    xs
}
#[cfg(test)] mod tests { use super::*; #[test] fn contract() { assert_eq!(norm(Vec::new()), Vec::<String>::new()); assert_eq!(norm(vec!["É".into(),"a".into(),"É".into(),"b".into()]), vec!["a".to_string(),"b".to_string(),"É".to_string()]); } }

pub fn norm(input: &[i32]) -> Vec<i32> {
    let mut xs: Vec<i32> = input.to_vec();
    xs.dedup();
    xs.sort();
    xs
}
#[cfg(test)] mod tests { use super::*; #[test] fn contract() { assert_eq!(norm(&[]),Vec::<i32>::new()); assert_eq!(norm(&[9,7,9,8,7]),vec![7,8,9]); } }

pub fn norm(input: &[&str]) -> Vec<String> {
    let mut xs: Vec<String> = input.iter().map(|s| s.trim().to_lowercase()).filter(|s| !s.is_empty()).collect();
    xs.dedup();
    xs.sort();
    xs
}
#[cfg(test)] mod tests { use super::*; #[test] fn contract() { assert_eq!(norm(&[" Z ","a","z","", " A "]),vec!["a".to_string(),"z".to_string()]); } }

