pub fn left(mut xs: Vec<i32>) -> Vec<i32> {
    xs.dedup();
    xs.sort();
    xs
}
pub fn right(mut ys: Vec<i32>) -> Vec<i32> {
    ys.dedup();
    ys.sort();
    ys
}
pub fn joined(a:Vec<i32>,b:Vec<i32>)->Vec<i32>{let mut out=left(a);out.extend(right(b));out}
#[cfg(test)] mod tests { use super::*; #[test] fn contract() { assert_eq!(joined(vec![7,8,7],vec![9,10,9]).len(),5); } }

pub fn upper(xs:&[i32])->Option<i32>{if xs.is_empty(){return None;}let mut best=0;for &x in xs {if x>best{best=x;}}Some(best)}
pub fn other(xs:&[i32])->Option<i32>{if xs.is_empty(){return None;}let mut best=0;for &x in xs {if x>best{best=x;}}Some(best)}
pub fn norm(mut xs: Vec<i32>) -> Vec<i32> {
    xs.dedup();
    xs.sort();
    xs
}
